'use client'

// The document layout primitives (PRD §6), rendering plan nodes from
// src/lib/documents/compose.ts for the HTML preview. Typography comes only from
// the --doc-* CSS variables generated by tokens.ts (`type()` below); this file
// names no font family and no font size.

import React, { useState, type CSSProperties } from 'react'

import { missingText, type KeyValueEntry, type PlanNode, type PlanRun, type PlanValue, type SourceEntry, type TotalsRow } from '@/lib/documents/compose'
import { CHART, type PrintTypeKey } from '@/lib/documents/tokens'

import styles from './documentPreview.module.css'

const PT_TO_PX = 96 / 72

type NodeOf<P extends PlanNode['primitive']> = Extract<PlanNode, { primitive: P }>

function kebab(key: string): string {
  return key.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`)
}

/** Inline style for a token text style. Every property is a CSS variable from tokens.ts. */
export function type(key: PrintTypeKey): CSSProperties {
  const p = `--doc-type-${kebab(key)}`
  return {
    fontFamily: `var(${p}-family)`,
    fontWeight: `var(${p}-weight)` as CSSProperties['fontWeight'],
    fontStyle: `var(${p}-style)`,
    fontSize: `var(${p}-size)`,
    lineHeight: `var(${p}-leading)`,
    letterSpacing: `var(${p}-tracking)`,
    textTransform: `var(${p}-case)` as CSSProperties['textTransform'],
    // Real italics/bolds only: never let the browser fake a missing cut.
    fontSynthesis: 'none',
    fontVariantNumeric: key === 'amount' || key === 'reference' || key === 'grandTotal' ? 'tabular-nums' : undefined,
  }
}

// ── Inline primitives: Citation, MissingField ────────────────────────────────

export function Citation({ numbers }: { numbers: readonly number[] }) {
  if (numbers.length === 0) return null
  return (
    <span className={styles.citation} style={type('citation')}>
      <span className={styles.srOnly}>Sources </span>[{numbers.join(', ')}]
    </span>
  )
}

export function MissingField({ value }: { value: Extract<PlanValue, { kind: 'missing' }> }) {
  return (
    <span className={styles.missing} data-required={value.required} data-field-id={value.fieldId} style={type('label')}>
      {missingText(value)}
    </span>
  )
}

function Unknown({ value }: { value: Extract<PlanValue, { kind: 'unknown' }> }) {
  return (
    <span className={styles.unknown}>
      <span style={type(value.style)}>{value.text}</span>
      {value.reasons.length > 0 && <span className={styles.unknownReasons} style={type('label')}>{value.reasons.join(' ')}</span>}
    </span>
  )
}

export function Value({ value }: { value: PlanValue }) {
  if (value.kind === 'missing') return <MissingField value={value} />
  if (value.kind === 'unknown') return <Unknown value={value} />
  return <span style={type(value.style)} className={styles.value}>{value.text}</span>
}

function Runs({ runs }: { runs: readonly PlanRun[] }) {
  return (
    <>
      {runs.map((r, i) => (
        <React.Fragment key={i}>
          {r.emphasis ? <em style={type('emphasis')}>{r.text}</em> : r.text}
          <Citation numbers={r.citations} />
        </React.Fragment>
      ))}
    </>
  )
}

// ── Block primitives ─────────────────────────────────────────────────────────

export function Letterhead({ node }: { node: NodeOf<'letterhead'> }) {
  const [broken, setBroken] = useState(false)
  const logo = node.logo
  return (
    <header className={styles.letterhead}>
      {logo.kind === 'image' && !broken
        ? (
          // eslint-disable-next-line @next/next/no-img-element -- local fixture asset; exporters read the same file
          <img className={styles.logo} src={logo.asset.src} alt={logo.asset.alt} onError={() => setBroken(true)} />
        )
        : (
          <span className={styles.logoFallback} style={type('label')} role="img" aria-label={broken ? 'Logo file could not be loaded; neutral placeholder shown' : 'No logo supplied; neutral placeholder shown'}>
            {logo.kind === 'none' ? logo.note : logo.brokenNote}
          </span>
        )}
      <p className={styles.issuerName} style={type('issuerName')}>{node.issuerName}</p>
    </header>
  )
}

export function TitleBlock({ node }: { node: NodeOf<'title-block'> }) {
  return (
    <div className={styles.titleBlock}>
      {node.draft && <p className={styles.draftMarker} style={type('draftMarker')}>{node.draft}</p>}
      <h1 className={styles.title}>
        <Value value={node.title} />
      </h1>
      {(node.reference || node.meta.length > 0) && (
        <dl className={styles.titleMeta}>
          {node.reference && <MetaItem label={node.reference.label} value={node.reference.value} />}
          {node.meta.map((e) => <MetaItem key={e.fieldId} label={e.label} value={e.value} />)}
        </dl>
      )}
    </div>
  )
}

function MetaItem({ label, value }: { label: string; value: PlanValue }) {
  return (
    <div className={styles.metaItem}>
      <dt className={styles.muted} style={type('label')}>{label}</dt>
      <dd><Value value={value} /></dd>
    </div>
  )
}

export function Summary({ node }: { node: NodeOf<'summary'> }) {
  return <p className={styles.summary} style={type('body')}><Runs runs={node.runs} /></p>
}

export function SectionHeading({ node }: { node: NodeOf<'section-heading'> }) {
  const Tag = node.level === 1 ? 'h2' : node.level === 2 ? 'h2' : 'h3'
  return <Tag className={styles.sectionHeading} style={type('sectionHeading')}>{node.text}</Tag>
}

export function Paragraph({ node }: { node: NodeOf<'paragraph'> }) {
  if (node.role === 'pull-quote') {
    return <blockquote className={styles.pullQuote} style={type('pullQuote')}><Runs runs={node.runs} /></blockquote>
  }
  return <p className={styles.paragraph} style={type('body')}><Runs runs={node.runs} /></p>
}

export function List({ node }: { node: NodeOf<'list'> }) {
  const Tag = node.ordered ? 'ol' : 'ul'
  return (
    <Tag className={styles.list} style={type('body')}>
      {node.items.map((item, i) => <li key={i}><Runs runs={item} /></li>)}
    </Tag>
  )
}

export function KeyValueField({ entry }: { entry: KeyValueEntry }) {
  return (
    <div className={styles.kvField} data-status={entry.value.kind} data-field-id={entry.fieldId}>
      <dt className={styles.muted} style={type('label')}>{entry.label}</dt>
      <dd><Value value={entry.value} /></dd>
    </div>
  )
}

export function KeyValueGroup({ node }: { node: NodeOf<'key-value-group'> }) {
  return (
    <section className={styles.kvGroup} aria-label={node.title}>
      {node.title && <h2 className={styles.groupTitle} style={type('label')}>{node.title}</h2>}
      <dl className={styles.kvList} data-layout={node.layout}>
        {node.entries.map((e) => <KeyValueField key={e.fieldId} entry={e} />)}
      </dl>
    </section>
  )
}

export function Table({ node }: { node: NodeOf<'table'> }) {
  return (
    <figure className={styles.figure}>
      <table className={styles.table}>
        {node.caption && <caption className={styles.caption} style={type('label')}>{node.caption}<Citation numbers={node.citations} /></caption>}
        <thead>
          <tr>{node.columns.map((c) => <th key={c.id} scope="col" data-align={c.align} style={type('tableHeader')}>{c.label}</th>)}</tr>
        </thead>
        <tbody>
          {node.rows.map((r) => (
            <tr key={r.id}>
              {r.cells.map((cell, i) => {
                const col = node.columns[i]
                return <td key={col?.id ?? i} data-align={col?.align} style={type(col?.numeric ? 'amount' : 'tableText')}>{cell}</td>
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </figure>
  )
}

export function InvoiceLineItems({ node }: { node: NodeOf<'invoice-line-items'> }) {
  return (
    <figure className={styles.figure}>
      <table className={`${styles.table} ${styles.lineItems}`}>
        {node.currencyNote && <caption className={styles.caption} style={type('label')}>{node.currencyNote}</caption>}
        <thead>
          <tr>
            <th scope="col" style={type('tableHeader')}>{node.headers.description}</th>
            <th scope="col" data-align="end" style={type('tableHeader')}>{node.headers.quantity}</th>
            <th scope="col" data-align="end" style={type('tableHeader')}>{node.headers.unitPrice}</th>
            <th scope="col" data-align="end" style={type('tableHeader')}>{node.headers.amount}</th>
          </tr>
        </thead>
        <tbody>
          {node.rows.map((r) => (
            <tr key={r.id} data-row-id={r.id}>
              <td style={type('tableText')}>{r.description}</td>
              <td data-align="end" style={type('amount')}>{r.quantity}</td>
              <td data-align="end"><Value value={r.unitPrice} /></td>
              <td data-align="end"><Value value={r.amount} /></td>
            </tr>
          ))}
        </tbody>
      </table>
    </figure>
  )
}

export function Totals({ node }: { node: NodeOf<'totals'> }) {
  const row = (r: TotalsRow, grand = false) => (
    <tr key={r.id} data-grand={grand || undefined}>
      <th scope="row" style={type(grand ? 'tableHeader' : 'tableText')}>{r.label}</th>
      <td data-align="end"><Value value={r.value} /></td>
    </tr>
  )
  return (
    <table className={styles.totals} data-complete={node.complete}>
      <caption className={styles.srOnly}>Totals{node.complete ? '' : ' (incomplete)'}</caption>
      <tbody>
        {node.rows.map((r) => row(r))}
        {row(node.grand, true)}
      </tbody>
    </table>
  )
}

export function Callout({ node }: { node: NodeOf<'callout'> }) {
  return (
    <aside className={styles.callout} data-tone={node.tone} data-audience={node.audience}>
      {node.label && <p className={styles.internalLabel} style={type('label')}>{node.label}</p>}
      <p style={type('body')}><Runs runs={node.runs} /></p>
    </aside>
  )
}

export function ImageWithCaption({ node }: { node: NodeOf<'image-with-caption'> }) {
  const [broken, setBroken] = useState(false)
  return (
    <figure className={styles.figure}>
      {broken
        ? <span className={styles.logoFallback} style={type('label')}>{node.brokenNote}</span>
        // eslint-disable-next-line @next/next/no-img-element -- local fixture asset
        : <img className={styles.image} src={node.asset.src} alt={node.asset.alt} onError={() => setBroken(true)} />}
      <figcaption className={styles.caption} style={type('label')}>{node.caption}<Citation numbers={node.citations} /></figcaption>
    </figure>
  )
}

export function ChartWithDataSummary({ node }: { node: NodeOf<'chart-with-data-summary'> }) {
  const series = node.series[0]
  const points = series?.points ?? []
  const labels = node.valueLabels[0] ?? []
  const max = Math.max(1, ...points.map((p) => p.y))
  // The viewBox is the content width in CSS px at 100% zoom, so one user unit is
  // one px and token text sizes (pt) render at their true size inside the SVG.
  const px = (pt: number) => pt * PT_TO_PX
  const w = px(node.contentWidthPt)
  const top = px(CHART.valueLabelBandPt), bottom = px(CHART.axisLabelBandPt)
  const h = top + px(CHART.plotHeightPt) + bottom
  const left = 0
  const band = (w - left) / Math.max(1, points.length)
  const summaryId = `${node.id}-summary`
  return (
    <figure className={styles.figure}>
      <figcaption className={styles.chartTitle} style={type('label')}>
        {node.title}<Citation numbers={node.citations} />
      </figcaption>
      <svg className={styles.chart} viewBox={`0 0 ${w} ${h}`} role="img" aria-label={`${node.title}. ${node.yLabel} by ${node.xLabel}.`} aria-describedby={summaryId}>
        <line x1={left} x2={w} y1={h - bottom} y2={h - bottom} className={styles.chartAxis} strokeWidth={px(CHART.axisStrokePt)} />
        {points.map((p, i) => {
          const barH = ((h - bottom - top) * p.y) / max
          const barW = band * CHART.barShare
          const x = left + i * band + (band - barW) / 2
          return (
            <g key={p.x}>
              <rect x={x} y={h - bottom - barH} width={barW} height={barH} className={styles.chartBar} />
              <text x={x + barW / 2} y={h - bottom - barH - px(CHART.valueLabelGapPt)} textAnchor="middle" className={styles.chartText} style={type('label')}>{labels[i]}</text>
              <text x={x + barW / 2} y={h - bottom + px(CHART.axisLabelBandPt) - px(CHART.valueLabelGapPt)} textAnchor="middle" className={styles.chartText} style={type('label')}>{p.x}</text>
            </g>
          )
        })}
      </svg>
      <p className={styles.chartAxes} style={type('label')}>{node.axesText}</p>
      <p id={summaryId} className={styles.chartSummary} style={type('label')}>{node.dataSummary}</p>
    </figure>
  )
}

export function SourceList({ node }: { node: NodeOf<'source-list'> }) {
  return (
    <ol className={styles.sourceList} style={type('citation')}>
      {node.entries.map((e: SourceEntry) => <li key={e.citationId} value={e.number} id={`source-${e.number}`}>{e.text}</li>)}
    </ol>
  )
}

export function PageBreakHint({ node, visible }: { node: NodeOf<'page-break-hint'>; visible: boolean }) {
  if (!visible) return <span className={styles.breakHint} data-break={node.kind} aria-hidden="true" />
  return <p className={styles.breakHintVisible} style={type('footer')} data-break={node.kind}>Preferred page break</p>
}

export function PageFooter({ node }: { node: NodeOf<'page-footer'> }) {
  return (
    <footer className={styles.footer} style={type('footer')}>
      <span>{node.identification}</span>
      <span>{node.pageLabel}</span>
    </footer>
  )
}

/** Renders one plan node with its primitive. */
export function PlanNodeView({ node, showHints = false }: { node: PlanNode; showHints?: boolean }) {
  switch (node.primitive) {
    case 'letterhead': return <Letterhead node={node} />
    case 'title-block': return <TitleBlock node={node} />
    case 'summary': return <Summary node={node} />
    case 'section-heading': return <SectionHeading node={node} />
    case 'paragraph': return <Paragraph node={node} />
    case 'list': return <List node={node} />
    case 'key-value-group': return <KeyValueGroup node={node} />
    case 'table': return <Table node={node} />
    case 'invoice-line-items': return <InvoiceLineItems node={node} />
    case 'totals': return <Totals node={node} />
    case 'callout': return <Callout node={node} />
    case 'image-with-caption': return <ImageWithCaption node={node} />
    case 'chart-with-data-summary': return <ChartWithDataSummary node={node} />
    case 'source-list': return <SourceList node={node} />
    case 'page-break-hint': return <PageBreakHint node={node} visible={showHints} />
    case 'page-footer': return <PageFooter node={node} />
  }
}
